import http from 'k6/http';
import { sleep } from 'k6';

export let options = {
  stages: [
    { duration: '2m', target: 5000 },
    { duration: '4m', target: 15000 },
    { duration: '4m', target: 15000 }
  ],
  thresholds: { 'http_req_duration': ['p(95)<120'] }
};

export default function () {
  const payload = JSON.stringify({ rider_id: __VU, pickup: 'lat,lng', dropoff: 'lat,lng', time: Date.now() });
  http.post('https://api.example.com/match', payload, { headers: { 'Content-Type': 'application/json' } });
  sleep(0.01);
}
```

## Follow-up Questions

- How would you validate autoscaling signals and cutover during a spike?
- How do you model geo-skew and its impact on partitioning and caching?
- What would you monitor to detect a bottleneck in the matchmaking hot path?

